export function assembleTypesenseServerConfig() {
  let TYPESENSE_SERVER_CONFIG = {
    apiKey: [REDACTED], // Be sure to use an API key that only allows searches, in production
    nodes: [
      {
        host: process.env.NEXT_PUBLIC_TYPESENSE_HOST,
        port: process.env.NEXT_PUBLIC_TYPESENSE_PORT,
        protocol: process.env.NEXT_PUBLIC_TYPESENSE_PROTOCOL,
      },
    ],
    numRetries: 8,
    connectionTimeoutSeconds: 1
  };

  if (process.env.NEXT_PUBLIC_TYPESENSE_HOST_2) {
    TYPESENSE_SERVER_CONFIG.nodes.push({
      host: process.env.NEXT_PUBLIC_TYPESENSE_HOST_2,
      port: process.env.NEXT_PUBLIC_TYPESENSE_PORT,
      protocol: process.env.NEXT_PUBLIC_TYPESENSE_PROTOCOL,
    });
  }

  if (process.env.NEXT_PUBLIC_TYPESENSE_HOST_3) {
    TYPESENSE_SERVER_CONFIG.nodes.push({
      host: process.env.NEXT_PUBLIC_TYPESENSE_HOST_3,
      port: process.env.NEXT_PUBLIC_TYPESENSE_PORT,
      protocol: process.env.NEXT_PUBLIC_TYPESENSE_PROTOCOL,
    });
  }

  if (process.env.NEXT_PUBLIC_TYPESENSE_HOST_NEAREST) {
    TYPESENSE_SERVER_CONFIG['nearestNode'] = {
      host: process.env.NEXT_PUBLIC_TYPESENSE_HOST_NEAREST,
      port: process.env.NEXT_PUBLIC_TYPESENSE_PORT,
      protocol: process.env.NEXT_PUBLIC_TYPESENSE_PROTOCOL,
    };
  }

  return TYPESENSE_SERVER_CONFIG
}

import Head from 'next/head';
import TypesenseInstantSearchAdapter from 'typesense-instantsearch-adapter';
import {
  InstantSearch,
  SearchBox,
  Hits,
  HierarchicalMenu,
  RefinementList,
  RangeInput,
  ToggleRefinement,
  ClearRefinements,
  Stats,
  HitsPerPage,
  SortBy,
  Pagination,
  InstantSearchSSRProvider,
  getServerState,
} from 'react-instantsearch';
import { Hit } from '../components/Hit';
import { assembleTypesenseServerConfig } from '../lib/utils';
import { renderToString } from 'react-dom/server';
import singletonRouter from 'next/router';
import { createInstantSearchRouterNext } from 'react-instantsearch-router-nextjs';

// Initialize the Typesense Instantsearch adapter: https://github.com/typesense/typesense-instantsearch-adapter
const TYPESENSE_SERVER_CONFIG = assembleTypesenseServerConfig();
const typesenseInstantsearchAdapter = new TypesenseInstantSearchAdapter({
  server: TYPESENSE_SERVER_CONFIG,
  additionalSearchParameters: {
    // The following parameters are directly passed to Typesense's search API endpoint.
    //  So you can pass any parameters supported by the search endpoint below.
    //  queryBy is required.
    query_by: 'name,categories,description',
    query_by_weights: '4,2,1',
    num_typos: 1,
    typo_tokens_threshold: 1,
    // groupBy: "categories",
    // groupLimit: 1
    // pinnedHits: "23:2"
  },
});

const transformItems = (items) => {
  return items.sort((a, b) => (a.label > b.label ? 1 : -1));
};

export default function Home({ serverState, serverUrl }) {
  return (
    <div>
      <Head>
        <title>Ecommerce Store with Typesense + Next.js + Vercel</title>
        <link rel='icon' href='/favicon.png' />
      </Head>

      <main>
        <InstantSearchSSRProvider {...serverState}>
          <InstantSearch
            indexName='products'
            searchClient={typesenseInstantsearchAdapter.searchClient}
            routing={{
              router: createInstantSearchRouterNext({
                singletonRouter,
                serverUrl,
                routerOptions: {
                  cleanUrlOnDispose: false,
                },
              }),
            }}
            future={{ preserveSharedStateOnUnmount: true }}
          >
            <div className='container-fluid px-md-5 pt-4'>
              <div className='row d-flex align-items-center'>
                <div className='col-md'>
                  <h1 className='display-6'>
                    Ecommerce Store with Typesense + Next.js + Vercel
                  </h1>
                </div>
                <div className='col-md-2 d-none d-md-block'>
                  <SearchBox classNames={{ loadingIcon: 'd-none' }} />
                </div>
              </div>

              <div className='lead mt-2'>
                Besides search experiences, Typesense can also be used to build{' '}
                <strong className='marker-highlight'>blazing fast</strong>,{' '}
                <strong className='marker-highlight'>
                  browsing experiences
                </strong>{' '}
                like product listing pages in an ecommerce store.
              </div>
              <ul className='lead mt-1'>
                <li>
                  Product data to render the grid is fetched by the front-end
                  from a{' '}
                  <strong>Geo-Distributed Typesense Cloud cluster</strong> with
                  nodes in Oregon, Frankfurt and Mumbai.
                </li>
                {/* eslint-disable-next-line react/no-unescaped-entities */}
                <li>
                  Product API Requests are routed to the node that is closest to
                  the user's location, like a CDN. Since data is geographically
                  distributed, this reduces latency even more for your users, as
                  they browse products.
                </li>
                <li>
                  The front-end uses Next.js, is statically generated and is
                  hosted on Vercel.
                </li>
                <li>
                  See{' '}
                  <a
                    href='https://github.com/typesense/showcase-nextjs-typesense-ecommerce-store'
                    target='_blank'
                    rel='noreferrer'
                  >
                    Source Code
                  </a>
                  .
                </li>
              </ul>

              <div className='row mt-4'>
                <div className='col-md-3 pr-md-5'>
                  <h5>Browse by Categories</h5>
                  <HierarchicalMenu
                    className='mt-3'
                    attributes={[
                      'categories.lvl0',
                      'categories.lvl1',
                      'categories.lvl2',
                      'categories.lvl3',
                    ]}
                    showParentLevel={true}
                    rootPath={'Cell Phones'}
                    limit={50}
                  />

                  <h5 className='mt-5'>Filter by Brands</h5>
                  <RefinementList
                    className='mt-3'
                    attribute='brand'
                    limit={10}
                    showMore={true}
                    showMoreLimit={50}
                    searchable={true}
                    transformItems={transformItems}
                  />

                  <div className='mt-2'>&nbsp;</div>

                  <ToggleRefinement
                    className='mt-5'
                    attribute='free_shipping'
                    label='Free Shipping'
                    value={true}
                  />

                  <div className='mt-1'>&nbsp;</div>

                  <h5 className='mt-5'>Filter by Price</h5>
                  <RangeInput attribute='price' />

                  <div className='mt-1'>&nbsp;</div>

                  <ClearRefinements className='mt-5' />
                </div>
                <div className='col-md'>
                  <div className='row mt-5 mt-md-0'>
                    <div className='col-md'>
                      <div className='row'>
                        <div className='col-md-4'></div>
                        <div className='col-md-8 d-flex justify-content-end align-items-center'>
                          <Stats
                            translations={{
                              stats(nbHits, processingTimeMS) {
                                let hitCountPhrase;
                                if (nbHits === 0) {
                                  hitCountPhrase = 'No products';
                                } else if (nbHits === 1) {
                                  hitCountPhrase = '1 product';
                                } else {
                                  hitCountPhrase = `${nbHits.toLocaleString()} products`;
                                }
                                return `${hitCountPhrase} found in ${processingTimeMS.toLocaleString()}ms`;
                              },
                            }}
                          />
                          <HitsPerPage
                            className='ms-4'
                            items={[
                              { label: '9 per page', value: 9, default: true },
                              { label: '18 per page', value: 18 },
                            ]}
                          />
                          <SortBy
                            items={[
                              { label: 'Relevancy', value: 'products' },
                              {
                                label: 'Price (asc)',
                                value: 'products/sort/price:asc',
                              },
                              {
                                label: 'Price (desc)',
                                value: 'products/sort/price:desc',
                              },
                            ]}
                            defaultValue='products'
                          />
                        </div>
                      </div>
                    </div>
                  </div>

                  <div className='row mt-1'>
                    <div className='col-sm'>
                      <Hits hitComponent={Hit} />
                    </div>
                  </div>

                  <div className='row'>
                    <div className='col-sm'>
                      <Pagination />
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </InstantSearch>
        </InstantSearchSSRProvider>
      </main>
    </div>
  );
}

export async function getServerSideProps({ req, res }) {
  res.setHeader(
    'Cache-Control',
    `s-maxage=${1 * 60 * 60}, stale-while-revalidate=${24 * 60 * 60}`
  );

  const protocol = req.headers.referer?.split('://')[0] || 'https';
  const serverUrl = `${protocol}://${req.headers.host}${req.url}`;
  const serverState = await getServerState(<Home serverUrl={serverUrl} />, {
    renderToString,
  });

  return {
    props: {
      serverState: JSON.parse(JSON.stringify(serverState)), // replace `undefined` (which isn't serializable) with `null`
      serverUrl,
    },
  };
}

require('dotenv').config();

const Typesense = require("typesense");

module.exports = (async () => {
  // Create a client
  const typesense = new Typesense.Client({
    nodes: [
      {
        host: process.env.TYPESENSE_HOST,
        port: process.env.TYPESENSE_PORT,
        protocol: process.env.TYPESENSE_PROTOCOL
      }
    ],
    apiKey: [REDACTED]
  });

  const schema = {
    name: "products",
    num_documents: 0,
    fields: [
      {
        name: "name",
        type: "string",
        facet: false
      },
      {
        name: "description",
        type: "string",
        facet: false
      },
      {
        name: "brand",
        type: "string",
        facet: true
      },
      {
        name: "categories",
        type: "string[]",
        facet: true
      },
      {
        name: "categories.lvl0",
        type: "string[]",
        facet: true
      },
      {
        name: "categories.lvl1",
        type: "string[]",
        facet: true,
        optional: true
      },
      {
        name: "categories.lvl2",
        type: "string[]",
        facet: true,
        optional: true
      },
      {
        name: "categories.lvl3",
        type: "string[]",
        facet: true,
        optional: true
      },
      {
        name: "price",
        type: "float",
        facet: true
      },
      {
        name: "image",
        type: "string",
        facet: false
      },
      {
        name: "popularity",
        type: "int32",
        facet: false
      },
      {
        name: "free_shipping",
        type: "bool",
        facet: true
      },
      {
        name: "rating",
        type: "int32",
        facet: true
      }
    ],
    default_sorting_field: "popularity"
  };

  console.log("Populating index in Typesense");

  const products = require("./data/ecommerce.json");

  let reindexNeeded = false;
  try {
    const collection = await typesense.collections("products").retrieve();
    console.log("Found existing schema");
    // console.log(JSON.stringify(collection, null, 2));
    if (
      collection.num_documents !== products.length ||
      process.env.FORCE_REINDEX === "true"
    ) {
      console.log("Deleting existing schema");
      reindexNeeded = true;
      await typesense.collections("products").delete();
    }
  } catch (e) {
    reindexNeeded = true;
  }

  if (!reindexNeeded) {
    return true;
  }

  console.log("Creating schema: ");
  console.log(JSON.stringify(schema, null, 2));
  await typesense.collections().create(schema);

  // const collectionRetrieved = await typesense
  //   .collections("products")
  //   .retrieve();
  // console.log("Retrieving created schema: ");
  // console.log(JSON.stringify(collectionRetrieved, null, 2));

  console.log("Adding records: ");

  // Bulk Import
  products.forEach(product => {
    product.free_shipping = product.name.length % 2 === 1; // We need this to be deterministic for tests
    product.rating = (product.description.length % 5) + 1; // We need this to be deterministic for tests
    product.categories.forEach((category, index) => {
      product[`categories.lvl${index}`] = [
        product.categories.slice(0, index + 1).join(" > ")
      ];
    });
  });

  try {
    const returnData = await typesense
      .collections("products")
      .documents()
      .import(products);
    console.log(returnData);
    console.log("Done indexing.");

    const failedItems = returnData.filter(item => item.success === false);
    if (failedItems.length > 0) {
      throw new Error(
        `Error indexing items ${JSON.stringify(failedItems, null, 2)}`
      );
    }

    return returnData;
  } catch (error) {
    console.log(error);
  }
})();

